    sg_buffer dst = sg_make_buffer(&(sg_buffer_desc){ .usage = { .vertex_buffer = true, .copy_dst = true }, .size = 256 });
    sg_commit();
    T(sg_isvalid());

    sg_destroy_buffer(dst);
