21626	_SOKOL_PRIVATE void _sg_vk_barrier_on_apply_bindings(VkCommandBuffer cmd_buf, const _sg_bindings_ptrs_t* bnd, bool is_compute_pass) {
21627	    SOKOL_ASSERT(bnd);
21628	    SOKOL_ASSERT(bnd->pip);
21629	    const _sg_shader_t* shd = _sg_shader_ref_ptr(&bnd->pip->cmn.shader);
21630	    if (is_compute_pass) {
21631	        for (size_t i = 0; i < SG_MAX_VIEW_BINDSLOTS; i++) {
21632	            const _sg_view_t* view = bnd->views[i];
21633	            if (0 == view) {
21634	                continue;
21635	            } else if (view->cmn.type == SG_VIEWTYPE_STORAGEBUFFER) {
21636	                _sg_buffer_t* buf = _sg_buffer_ref_ptr(&view->cmn.buf.ref);
21637	                _sg_vk_access_t new_access = shd->cmn.views[i].sbuf_readonly
21638	                    ? _SG_VK_ACCESS_STORAGEBUFFER_RO
21639	                    : _SG_VK_ACCESS_STORAGEBUFFER_RW_COMPUTE;
21640	                _sg_vk_buffer_barrier(cmd_buf, buf, new_access);
21641	                _sg_track_add(&_sg.vk.track.buffers, buf->slot.id);
21642	            } else if (view->cmn.type == SG_VIEWTYPE_STORAGEIMAGE) {
21643	                _sg_image_t* img = _sg_image_ref_ptr(&view->cmn.img.ref);
21644	                _sg_vk_image_barrier(cmd_buf, img, _SG_VK_ACCESS_STORAGEIMAGE);
21645	                _sg_track_add(&_sg.vk.track.images, img->slot.id);
21646	            } else if (view->cmn.type == SG_VIEWTYPE_TEXTURE) {
21647	                _sg_image_t* img = _sg_image_ref_ptr(&view->cmn.img.ref);
21648	                _sg_vk_image_barrier(cmd_buf, img, _SG_VK_ACCESS_TEXTURE);
21649	                _sg_track_add(&_sg.vk.track.images, img->slot.id);
21650	            } else {
21651	                SOKOL_UNREACHABLE;
21652	            }
21653	        }
21654	    } else {
21655	        // No transitions allowed in render passes, but fragment-writable-storage buffer
21656	        // need to be tracked for transitioning in sg_end_pass. Other than that we're
21657	        // only checking here if the cur_access flag has expected bits set
21658	        //
21659	        // NOTE: the write-transient exception is necessary because of
21660	        //  https://github.com/floooh/sokol/issues/1598
21661	        //
21662	        // Technically this check should go into the validation layer!
21663	        for (size_t i = 0; i < SG_MAX_VERTEXBUFFER_BINDSLOTS; i++) {
21664	            if (bnd->vbs[i] && !bnd->vbs[i]->cmn.usage.write_transient) {
21665	                SOKOL_ASSERT(0 != (bnd->vbs[i]->vk.cur_access & _SG_VK_ACCESS_VERTEXBUFFER));
21666	            }
21667	        }
21668	        if (bnd->ib && !bnd->ib->cmn.usage.write_transient) {
21669	            SOKOL_ASSERT(0 != (bnd->ib->vk.cur_access & _SG_VK_ACCESS_INDEXBUFFER));
21670	        }
21671	        for (size_t i = 0; i < SG_MAX_VIEW_BINDSLOTS; i++) {
21672	            const _sg_view_t* view = bnd->views[i];
21673	            if (0 == view) {
21674	                continue;
21675	            }
21676	            else if (view->cmn.type == SG_VIEWTYPE_STORAGEBUFFER) {
21677	                _sg_buffer_t* buf = _sg_buffer_ref_ptr(&view->cmn.buf.ref);
21678	                if (shd->cmn.views[i].sbuf_readonly) {
21679	                    if (!buf->cmn.usage.write_transient) {
21680	                        SOKOL_ASSERT(0 != (buf->vk.cur_access & _SG_VK_ACCESS_STORAGEBUFFER_RO));
21681	                    }
21682	                } else {
21683	                    SOKOL_ASSERT((buf->vk.cur_access == _sg_vk_default_buffer_access_mask(buf)) || (buf->vk.cur_access == _SG_VK_ACCESS_STORAGEBUFFER_RW_FRAGMENT));
21684	                    // only record new rw-access, the actual barrier will be deferred to sg_end_pass
21685	                    buf->vk.cur_access = _SG_VK_ACCESS_STORAGEBUFFER_RW_FRAGMENT;
21686	                    _sg_track_add(&_sg.vk.track.buffers, buf->slot.id);
21687	                }
21688	            } else if (view->cmn.type == SG_VIEWTYPE_TEXTURE) {
21689	                const _sg_image_t* img = _sg_image_ref_ptr(&view->cmn.img.ref);
21690	                if (!img->cmn.usage.write_transient) {
21691	                    SOKOL_ASSERT(0 != (img->vk.cur_access & _SG_VK_ACCESS_TEXTURE));
21692	                }
21693	            } else {
21694	                SOKOL_UNREACHABLE;
21695	            }
21696	        }
21697	    }
21698	}
