21706	        const uint32_t buf_id = _sg.vk.track.buffers.slots[i];
21707	        _sg_buffer_t* buf = _sg_lookup_buffer(buf_id);
21708	        if (buf) {
21709	            _sg_vk_buffer_barrier(cmd_buf, buf, _sg_vk_default_buffer_access_mask(buf));
21710	        }
21711	    }
21712	    _sg_track_reset(&_sg.vk.track.buffers);
21713	
21714	    if (is_compute_pass) {
