21716	        for (int i = 0; i < _sg.vk.track.images.cur_slot; i++) {
21717	            const uint32_t img_id = _sg.vk.track.images.slots[i];
21718	            _sg_image_t* img = _sg_lookup_image(img_id);
21719	            if (img) {
21720	                _sg_vk_image_barrier(cmd_buf, img, _sg_vk_default_image_access_mask(img));
